use wasmtime::{Engine,Module,ExternType,ValType};
fn val(v:ValType)-> &'static str { match v {ValType::I32=>"i32",ValType::I64=>"i64",ValType::F32=>"f32",ValType::F64=>"f64",_=>panic!("unsupported value")}}
fn main(){let e=Engine::default();let m=Module::from_file(&e,"raw.wasm").unwrap();println!("(module");let mut exports=Vec::new();for (i,x) in m.exports().enumerate(){let name=x.name();let ty=match x.ty(){ExternType::Func(f)=>format!("func $item{i} {} {}",f.params().map(|v|format!("(param {})",val(v))).collect::<Vec<_>>().join(" "),f.results().map(|v|format!("(result {})",val(v))).collect::<Vec<_>>().join(" ")),ExternType::Memory(mem)=>format!("memory $item{i} {}",mem.minimum()),ExternType::Global(g)=>format!("global $item{i} {}",val(g.content().clone())),_=>panic!("unsupported export")};let kind=ty.split(' ').next().unwrap();println!("(import \"rust-implementation\" \"{name}\" ({ty}))");exports.push(format!("(export \"{name}\" ({kind} $item{i}))"));}for x in exports{println!("{x}")}println!(")");}
